// === Tab: mySketch ===
let dot = []
let counter=0
let STROKEWEIGHT=1.5
let ConecDis=100

function setup()
{
  createCanvas(windowWidth, windowHeight);
  background(100);

	for (let i = 0; i < 200; i++) //create 20 coins
	{
		dot[i] =  new A_dot()
	}

}

function draw()
{
	counter++
	if(counter%round(random(50,80))==0)
	{
		STROKEWEIGHT=random(.5,2)
		ConecDis=random(80,250)
		for (let i = 0; i < 200; i++) //create 20 coins
		{
			dot[i].c=[random(255),random(255),random(255),random(255)]
		}
	}
	for (let i = 0; i < 200; i++) //create 20 coins
	{
		dot[i].move()
		dot[i].show()
	  for (let j = i + 1; j < dot.length; j++) 
	  {
			if(dot[i].nextTo(dot[j],ConecDis)) 
			{
				stroke(dot[i].c);
				strokeWeight(STROKEWEIGHT)
				line(dot[i].x, dot[i].y, dot[j].x, dot[j].y);
			}
		}
	}
}
class A_dot
{
  constructor()
  {
		this.c=[random(255),random(255),random(255),random(255)]
    this.x = random(width)
    this.y = random(height)
		this.velX=random(-3.5,3.5)
		this.velY=random(-3.5,3.5)
  }

	move()
	{

		this.x=this.x + this.velX
		this.y=this.y + this.velY

		if(this.x>width+30 || this.x <-30) 
		{ 
			this.velX=this.velX * -1
		}
		if(this.y>height+30 || this.y <-30) 
		{
			this.velY=this.velY * -1
		}
	}
	show()
	{
		circle(this.x,this.y,1)
	}

	nextTo(other,ConecDis) 
	{
    let d = dist(this.x, this.y, other.x, other.y);
    return d < ConecDis
  }
}

